<?php
require_once __DIR__.'/../app/core/bootstrap.php';
$u=require_role(['admin']);
function admin_upload_image(string $field,string $fallback): string { if(empty($_FILES[$field]['name']) || ($_FILES[$field]['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK) return $fallback; if($_FILES[$field]['size']>4*1024*1024) return $fallback; $ext=strtolower(pathinfo($_FILES[$field]['name'],PATHINFO_EXTENSION)); if(!in_array($ext,['jpg','jpeg','png','webp'],true)) return $fallback; $dir=__DIR__.'/../assets/uploads'; if(!is_dir($dir)) @mkdir($dir,0755,true); $name='admin_'.date('YmdHis').'_'.bin2hex(random_bytes(4)).'.'.$ext; return move_uploaded_file($_FILES[$field]['tmp_name'],$dir.'/'.$name)?'uploads/'.$name:$fallback; }

$tab=$_GET['tab']??'overview'; $action=$_POST['action']??'';
if(is_post()){
 verify_csrf();
 if($action==='approve_user'){ $id=(int)$_POST['id']; query("UPDATE users SET status='active' WHERE id=?",'i',[$id]); safe_log('activate_user','user',$id); flash('success','User activated.'); redirect('admin/index.php?tab=users'); }
 if($action==='toggle_listing'){ $table=$_POST['table'];$id=(int)$_POST['id'];$allowed=['tours','accommodations','transports','activities','destinations']; if(in_array($table,$allowed,true)){ $new=$_POST['new_status']==='active'?'active':'pending'; query("UPDATE {$table} SET status=? WHERE id=?",'si',[$new,$id]); safe_log('listing_status','listing',$id,['table'=>$table,'status'=>$new]); flash('success','Listing status updated.'); } redirect('admin/index.php?tab=listings'); }
 if($action==='approve_payment' || $action==='reject_payment'){
   $pid=(int)$_POST['payment_id']; $p=query('SELECT * FROM payments WHERE id=? LIMIT 1','i',[$pid])->fetch_assoc();
   if($p){ if($action==='approve_payment'){query("UPDATE payments SET status='paid',paid_at=NOW(),verified_by=?,verified_at=NOW() WHERE id=?",'ii',[$u['id'],$pid]);query("UPDATE bookings SET payment_status='paid',status='confirmed' WHERE id=?",'i',[$p['booking_id']]); safe_log('approve_payment','payment',$pid,['booking_id'=>$p['booking_id']]); flash('success','Payment approved and booking confirmed.');} else {query("UPDATE payments SET status='failed',verified_by=?,verified_at=NOW() WHERE id=?",'ii',[$u['id'],$pid]);query("UPDATE bookings SET payment_status='failed',status='pending_payment' WHERE id=?",'i',[$p['booking_id']]); safe_log('reject_payment','payment',$pid,['booking_id'=>$p['booking_id']]); flash('success','Payment rejected. Customer can submit again.');} }
   redirect('admin/index.php?tab=payments');
 }
 if($action==='edit_tour'){
   $id=(int)($_POST['id']??0);
   $titleText=trim($_POST['title']??'');
   $short=trim($_POST['short_description']??'');
   $description=trim($_POST['description']??'');
   $days=max(1,(int)($_POST['duration_days']??1));
   $price=max(0,(float)($_POST['base_price']??0));
   $maxGuests=max(1,(int)($_POST['max_guests']??1));
   $status=in_array($_POST['status']??'pending',['active','pending','draft','rejected'],true)?$_POST['status']:'pending';
   $tour=query('SELECT * FROM tours WHERE id=? LIMIT 1','i',[$id])->fetch_assoc();
   if(!$tour || $titleText===''){ flash('error','Tour title and a valid tour are required.'); redirect('admin/index.php?tab=listings'); }
   $image=admin_upload_image('image',$tour['image']??'tour.svg');
   query('UPDATE tours SET title=?,short_description=?,description=?,duration_days=?,base_price=?,max_guests=?,image=?,status=? WHERE id=?','sssidsisi',[$titleText,$short,$description,$days,$price,$maxGuests,$image,$status,$id]);
   safe_log('edit_tour','tour',$id,['title'=>$titleText,'base_price'=>$price,'status'=>$status]);
   flash('success','Tour updated successfully.');
   redirect('admin/index.php?tab=listings');
 }
 if($action==='delete_tour'){
   $id=(int)($_POST['id']??0);
   $tour=query('SELECT * FROM tours WHERE id=? LIMIT 1','i',[$id])->fetch_assoc();
   if(!$tour){ flash('error','Tour not found.'); redirect('admin/index.php?tab=listings'); }
   $bookingCount=(int)(query('SELECT COUNT(*) n FROM bookings WHERE tour_id=?','i',[$id])->fetch_assoc()['n']??0);
   if($bookingCount>0){
      query("UPDATE tours SET status='draft' WHERE id=?",'i',[$id]);
      flash('error','This tour has booking history, so it was moved to Draft instead of being permanently deleted.');
      safe_log('archive_tour','tour',$id,['bookings'=>$bookingCount]);
   } else {
      query('DELETE FROM tours WHERE id=?','i',[$id]);
      safe_log('delete_tour','tour',$id,['title'=>$tour['title']??'']);
      flash('success','Tour deleted.');
   }
   redirect('admin/index.php?tab=listings');
 }
 if($action==='add_destination'){ $name=trim($_POST['name']);$slug=slugify($name);$desc=trim($_POST['description']);$area=trim($_POST['area']??'Arusha');$img=admin_upload_image('image','park.svg');query('INSERT INTO destinations(name,slug,description,area,image,status,created_by) VALUES(?,?,?,?,?,\'active\',?)','sssssi',[$name,$slug,$desc,$area,$img,$u['id']]);flash('success','Destination added.');redirect('admin/index.php?tab=content'); }
 if($action==='save_settings'){ $keys=['payment_mobile_money','payment_bank','payment_control_number','payment_paypal','paypal_link','paypal_client_id','paypal_secret']; foreach($keys as $key){$value=trim($_POST[$key]??'');$st=db()->prepare('INSERT INTO settings(key_name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)');$st->bind_param('ss',$key,$value);$st->execute();} flash('success','Payment settings saved.');redirect('admin/index.php?tab=settings'); }
}
$stats=['tours'=>query("SELECT COUNT(*) n FROM tours WHERE status='active'")->fetch_assoc()['n'],'bookings'=>query("SELECT COUNT(*) n FROM bookings")->fetch_assoc()['n'],'pending_payments'=>query("SELECT COUNT(*) n FROM payments WHERE status='pending'")->fetch_assoc()['n'],'operators'=>query("SELECT COUNT(*) n FROM users WHERE role='operator' AND status='active'")->fetch_assoc()['n']];
$bookings=query("SELECT b.*,t.title tour FROM bookings b JOIN tours t ON t.id=b.tour_id ORDER BY b.id DESC LIMIT 30")->fetch_all(MYSQLI_ASSOC);
$payments=query("SELECT p.*,b.reference,b.customer_name,b.customer_email,b.total_amount,t.title tour FROM payments p JOIN bookings b ON b.id=p.booking_id JOIN tours t ON t.id=b.tour_id ORDER BY p.id DESC LIMIT 40")->fetch_all(MYSQLI_ASSOC);
$users=query("SELECT * FROM users ORDER BY created_at DESC")->fetch_all(MYSQLI_ASSOC);
$tours=query("SELECT t.*,u.name operator_name FROM tours t LEFT JOIN users u ON u.id=t.operator_id ORDER BY t.id DESC")->fetch_all(MYSQLI_ASSOC);
$acc=query("SELECT a.*,u.name operator_name FROM accommodations a LEFT JOIN users u ON u.id=a.operator_id ORDER BY a.id DESC")->fetch_all(MYSQLI_ASSOC);
$trs=query("SELECT t.*,u.name operator_name FROM transports t LEFT JOIN users u ON u.id=t.operator_id ORDER BY t.id DESC")->fetch_all(MYSQLI_ASSOC);
$acts=query("SELECT a.*,u.name operator_name FROM activities a LEFT JOIN users u ON u.id=a.operator_id ORDER BY a.id DESC")->fetch_all(MYSQLI_ASSOC);
$editTourId=(int)($_GET['edit_tour']??0);
$editTour=$editTourId>0?query('SELECT * FROM tours WHERE id=? LIMIT 1','i',[$editTourId])->fetch_assoc():null;
$title=['overview'=>'Dashboard','bookings'=>'Bookings','payments'=>'Payments & Verification','listings'=>'Listings','users'=>'Users & Operators','content'=>'Arusha Content','settings'=>'System Settings'][$tab]??'Admin Dashboard';
require __DIR__.'/../app/views/portal_header.php';
?>
<?php if($tab==='overview'): ?>
<div class="portal-hero"><div class="eyebrow">Owner control centre</div><h2 style="font:800 48px Georgia,serif;margin:8px 0;max-width:680px">Wildvista command centre, <?=e($u['name'])?>.</h2><p style="max-width:640px;color:#d9e9e2">Control Arusha inventory, bookings, payments, operators and the live customer experience from one place.</p></div>
<div class="portal-grid-4" style="margin-top:18px"><div class="metric-card"><span class="metric-label">ACTIVE TOURS</span><div class="metric"><?=$stats['tours']?></div></div><div class="metric-card"><span class="metric-label">TOTAL BOOKINGS</span><div class="metric"><?=$stats['bookings']?></div></div><div class="metric-card"><span class="metric-label">PENDING PAYMENTS</span><div class="metric"><?=$stats['pending_payments']?></div></div><div class="metric-card"><span class="metric-label">ACTIVE OPERATORS</span><div class="metric"><?=$stats['operators']?></div></div></div>
<div class="portal-grid-2" style="margin-top:18px"><div class="portal-card"><div class="section-head"><div><h2>Recent bookings</h2><p class="muted">Latest customer activity.</p></div><a href="?tab=bookings">View all →</a></div><div class="table-wrap"><table><tr><th>Customer</th><th>Trip</th><th>Status</th><th>Total</th></tr><?php foreach(array_slice($bookings,0,8) as $b): ?><tr><td><?=e($b['customer_name'])?></td><td><?=e($b['tour'])?></td><td><span class="tag <?=($b['status']==='pending_payment'?'pending':($b['status']==='cancelled'?'danger':''))?>"><?=e(str_replace('_',' ',$b['status']))?></span></td><td><?=money((float)$b['total_amount'])?></td></tr><?php endforeach; ?></table></div></div><div class="portal-card"><h2>Quick actions</h2><p class="muted">Jump straight into owner tasks.</p><div class="quick-actions"><a class="quick-action" href="?tab=payments"><strong>✓ Verify payments</strong><small class="muted">Review submitted transaction IDs.</small></a><a class="quick-action" href="?tab=listings"><strong>◈ Manage listings</strong><small class="muted">Activate pending catalogue items.</small></a><a class="quick-action" href="?tab=users"><strong>♙ Operators</strong><small class="muted">Approve partner accounts.</small></a><a class="quick-action" href="?tab=settings"><strong>⚙ Payment settings</strong><small class="muted">Set numbers and PayPal details.</small></a></div></div></div>
<?php elseif($tab==='payments'): ?>
<div class="portal-card"><div class="section-head"><div><h2>Payment verification</h2><p class="muted">Customers can submit mobile-money, bank, control-number or PayPal references. Approve only after checking the payment.</p></div></div><div class="table-wrap"><table><tr><th>Booking</th><th>Customer</th><th>Method</th><th>Reference</th><th>Amount</th><th>Proof</th><th>Status</th><th>Action</th></tr><?php foreach($payments as $p): ?><tr><td><strong><?=e($p['reference'])?></strong><br><small><?=e($p['tour'])?></small></td><td><?=e($p['customer_name'])?><br><small><?=e($p['customer_email'])?></small></td><td><?=e(str_replace('_',' ',$p['method']))?></td><td><?=e($p['transaction_ref']?:'—')?></td><td><?=money((float)$p['amount'])?></td><td><?php if(!empty($p['proof_path'])): ?><a href="<?=url($p['proof_path'])?>" target="_blank">View</a><?php else: ?>—<?php endif; ?></td><td><span class="tag <?=($p['status']==='pending'?'pending':($p['status']==='failed'?'danger':''))?>"><?=e($p['status'])?></span></td><td><?php if($p['status']==='pending'): ?><form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="approve_payment"><input type="hidden" name="payment_id" value="<?=$p['id']?>"><button class="btn" style="padding:8px 10px">Approve</button></form> <form method="post" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="reject_payment"><input type="hidden" name="payment_id" value="<?=$p['id']?>"><button class="btn btn-light" style="padding:8px 10px">Reject</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></table></div></div>
<?php elseif($tab==='bookings'): ?>
<div class="portal-card"><div class="section-head"><div><h2>Bookings</h2><p class="muted">Every booking is visible immediately, even before payment.</p></div></div><div class="table-wrap"><table><tr><th>Ref</th><th>Customer</th><th>Trip</th><th>Date</th><th>Total</th><th>Payment</th><th>Status</th></tr><?php foreach($bookings as $b): ?><tr><td><strong><?=e($b['reference'])?></strong></td><td><?=e($b['customer_name'])?><br><small><?=e($b['customer_email'])?></small></td><td><?=e($b['tour'])?></td><td><?=e($b['booking_date'])?></td><td><?=money((float)$b['total_amount'])?></td><td><?=e($b['payment_status'])?></td><td><?=e(str_replace('_',' ',$b['status']))?></td></tr><?php endforeach; ?></table></div></div>
<?php elseif($tab==='users'): ?>
<div class="portal-card"><div class="section-head"><div><h2>Users & operators</h2><p class="muted">Approve accounts before they manage live inventory.</p></div></div><div class="table-wrap"><table><tr><th>Name</th><th>Email</th><th>Phone</th><th>Role</th><th>Status</th><th>Action</th></tr><?php foreach($users as $x): ?><tr><td><?=e($x['name'])?></td><td><?=e($x['email'])?></td><td><?=e($x['phone'])?></td><td><?=e($x['role'])?></td><td><?=e($x['status'])?></td><td><?php if($x['status']==='pending'): ?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="approve_user"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn">Activate</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></table></div></div>
<?php elseif($tab==='listings'): ?>
<?php if($editTour): ?>
<div class="portal-card" style="margin-bottom:18px"><div class="section-head"><div><h2>Edit tour</h2><p class="muted">Changes are saved directly to the existing tour.</p></div><a href="<?=url('admin/index.php?tab=listings')?>">Close</a></div><form method="post" enctype="multipart/form-data" class="portal-grid-2"><?=csrf_field()?><input type="hidden" name="action" value="edit_tour"><input type="hidden" name="id" value="<?=$editTour['id']?>"><div><label>Tour title</label><input name="title" value="<?=e($editTour['title'])?>" required><label>Short description</label><input name="short_description" value="<?=e($editTour['short_description'])?>"><label>Description</label><textarea name="description" required><?=e($editTour['description'])?></textarea></div><div><label>Duration (days)</label><input type="number" min="1" name="duration_days" value="<?=$editTour['duration_days']?>" required><label>Base price</label><input type="number" min="0" step="0.01" name="base_price" value="<?=$editTour['base_price']?>" required><label>Maximum guests</label><input type="number" min="1" name="max_guests" value="<?=$editTour['max_guests']?>" required><label>Status</label><select name="status"><option value="active" <?=($editTour['status']==='active'?'selected':'')?>>Active</option><option value="pending" <?=($editTour['status']==='pending'?'selected':'')?>>Pending</option><option value="draft" <?=($editTour['status']==='draft'?'selected':'')?>>Draft</option><option value="rejected" <?=($editTour['status']==='rejected'?'selected':'')?>>Rejected</option></select><label>New image (optional)</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"><button class="btn btn-dark" style="margin-top:14px">Save tour</button></div></form></div>
<?php endif; ?>
<?php $groups=[['Tours',$tours,'tours','title'],['Accommodation',$acc,'accommodations','name'],['Transport',$trs,'transports','name'],['Activities',$acts,'activities','name']]; foreach($groups as $g): ?><div class="portal-card" style="margin-bottom:18px"><div class="section-head"><div><h2><?=e($g[0])?></h2><p class="muted">Operator-owned and Wildvista catalogue items.</p></div></div><div class="table-wrap"><table><tr><th>Name</th><th>Owner</th><th>Status</th><th>Action</th></tr><?php foreach($g[1] as $r): ?><tr><td><?=e($r[$g[3]])?></td><td><?=e($r['operator_name']??'Wildvista catalogue')?></td><td><span class="tag <?=($r['status']!=='active'?'pending':'')?>"><?=e($r['status'])?></span></td><td><div style="display:flex;gap:6px;flex-wrap:wrap"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="toggle_listing"><input type="hidden" name="table" value="<?=e($g[2])?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="new_status" value="<?=$r['status']==='active'?'pending':'active'?>"><button class="btn" style="padding:8px 10px"><?=$r['status']==='active'?'Set pending':'Activate'?></button></form><?php if($g[2]==='tours'): ?><a class="btn btn-light" style="padding:8px 10px" href="<?=url('admin/index.php?tab=listings&edit_tour='.$r['id'])?>">Edit</a><form method="post" onsubmit="return confirm('Delete this tour? If it has booking history, Wildvista will keep it and move it to Draft.');"><?=csrf_field()?><input type="hidden" name="action" value="delete_tour"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-light" style="padding:8px 10px" type="submit">Delete</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></table></div></div><?php endforeach; ?>
<?php elseif($tab==='content'): ?>
<div class="portal-grid-2"><form class="portal-card" method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="add_destination"><h2>Add Arusha destination</h2><p class="muted">Catalogue data can exist before an operator claims it.</p><label>Name</label><input name="name" required><label>Description</label><textarea name="description" required></textarea><label>Area / location</label><input name="area" value="Arusha"><label>Photo</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"><small class="muted">Upload the park/destination photo. JPG, PNG or WEBP, max 4MB.</small><button class="btn btn-dark" style="margin-top:14px">Add destination</button></form><div class="portal-card"><h2>Content principle</h2><p class="muted">Pending listings can be prepared as catalogue data, while only verified/active listings enter the live booking selection.</p><div class="notice">Do not present an unclaimed property as a Wildvista partner until an admin verifies it.</div></div></div>
<?php elseif($tab==='settings'): ?>
<form class="portal-grid-2" method="post"><?=csrf_field()?><input type="hidden" name="action" value="save_settings"><div class="portal-card"><h2>Customer payment instructions</h2><p class="muted">These are shown on the payment page after a booking is created.</p><label>Mobile money instructions</label><textarea name="payment_mobile_money" placeholder="Example: Pay to Wildvista Tigo Pesa / Airtel Money number..."><?=e(setting('payment_mobile_money'))?></textarea><label>Bank transfer instructions</label><textarea name="payment_bank" placeholder="Bank name, account name, account number, SWIFT..."><?=e(setting('payment_bank'))?></textarea><label>Control / Lipa number instructions</label><textarea name="payment_control_number" placeholder="How the customer gets and pays the control number..."><?=e(setting('payment_control_number'))?></textarea><label>PayPal instructions</label><textarea name="payment_paypal" placeholder="PayPal account/email and customer instructions..."><?=e(setting('payment_paypal'))?></textarea></div><div class="portal-card"><h2>Optional PayPal API</h2><p class="muted">Leave blank to use manual PayPal transaction-reference verification. When credentials are supplied, an automatic adapter can be enabled without changing the booking core.</p><label>PayPal payment link (manual)</label><input name="paypal_link" value="<?=e(setting('paypal_link'))?>" placeholder="https://paypal.me/youraccount"><label>PayPal Client ID</label><input name="paypal_client_id" value="<?=e(setting('paypal_client_id'))?>"><label>PayPal Secret</label><input type="password" name="paypal_secret" value="<?=e(setting('paypal_secret'))?>"><div class="notice"><strong>Live safety:</strong> never put PayPal secrets in public JavaScript. Keep them server-side only.</div><button class="btn btn-dark" style="margin-top:14px">Save payment settings</button></div></form>
<?php endif; ?>
